script:
ship_event = {
	id = federations2.1
	title = federations2.1.name
	desc = federations2.1.desc
	picture = GFX_evt_warm_barren
	show_sound = event_radio_chatter
	location = FROM

	is_triggered_only = yes
	auto_opens = yes

	immediate = {
		owner = {
			if = {
				limit = {
					NOT = {
						owner = {
							OR = {
								is_human_prescripted_empire = yes
								has_country_flag = human_plantoid
								is_human_species = yes
							}
						}
					}
				}
				create_leader = {
					class = scientist
					species = owner_main_species
					effect = {
						save_event_target_as = shakespeare
						exile_leader_as = shakespeare
					}
				}
			}
			else = {
				create_leader = {
					class = scientist
					name = "NAME_William_Shakespeare"
					species = owner_main_species
					effect = {
						save_event_target_as = shakespeare
						exile_leader_as = shakespeare
