			owner = {
				is_xenophile = no
			}
		}
		owner = {
			add_modifier = {
				modifier = supremacy_reaffirmed_by_gift
				years = 5
			}
		}
	}
	option = {
		name = federations2.1.B
		trigger = {
			owner = {
				is_xenophobe = yes
			}
		}
		if = {
			limit = {
				owner = {
					OR = {
						is_dictatorial_authority = yes
						is_imperial_authority = yes
